mapper.select:
SELECT s.no,s.name_ja,s.name_kana,s.name_ko,s.sake_type,s.image_url AS imageUrl,br.name_ko AS breweryNameKo,ba.name_ko AS brandNameKo,br.prefecture FROM SAKE s JOIN BREWERY br ON s.brewery_no=br.no LEFT JOIN BRAND ba ON s.brand_no=ba.no
AND (s.name_ko LIKE CONCAT('%',#{fd,jdbcType=VARCHAR},'%') OR s.name_kana LIKE CONCAT('%',#{fd,jdbcType=VARCHAR},'%') OR s.name_ja LIKE CONCAT('%',#{fd,jdbcType=VARCHAR},'%'))
AND sake_type=#{sakeType}
ORDER BY s.image_url IS NOT NULL DESC,s.no DESC LIMIT 12 OFFSET #{start}

SELECT COUNT(*) FROM SAKE s
AND (s.name_ko LIKE CONCAT('%',#{fd,jdbcType=VARCHAR},'%') OR s.name_kana LIKE CONCAT('%',#{fd,jdbcType=VARCHAR},'%') OR s.name_ja LIKE CONCAT('%',#{fd,jdbcType=VARCHAR},'%'))
AND s.sake_type=#{sakeType}
